/* FONT FACES */
/* https://jadapps.app/font-tools/guides/font-to-base64-data-uri-online */

@charset "UTF-8";

/* --FONT-INTERFACE-THEME, SANS-SERIF */
@font-face {
	font-family: "Alegreya Sans";
	src: url("data:font/ttf;base64,")
		format("truetype");
	font-style: normal;
	font-weight: normal;
	font-display: swap;
}
@font-face {
	font-family: "Alegreya Sans";
	src: url("data:font/ttf;base64,")
		format("truetype");
	font-style: normal;
	font-weight: bold;
	font-display: swap;
}
@font-face {
	font-family: "Alegreya Sans";
	src: url("data:font/ttf;base64,")
		format("truetype");
	font-style: italic;
	font-weight: normal;
	font-display: swap;
}
@font-face {
	font-family: "Alegreya Sans";
	src: url("data:font/ttf;base64,")
		format("truetype");
	font-style: italic;
	font-weight: bold;
	font-display: swap;
}
/* libertinus sans, regular only */
@font-face {
	font-family: "Libertinus Sans";
	src: url("data:font/otf;base64,")
		format("opentype");
	font-display: swap;
}
/* cmu concrete, regular only */
@font-face {
	font-family: "CMU Concrete";
	src: url("data:font/otf;base64,")
		format("opentype");
	font-display: swap;
}

/* --FONT-TEXT-THEME, SERIF */
@font-face {
	font-family: "Alegreya";
	src: url("data:font/ttf;base64,")
		format("truetype-variations");
	/* font-weight: not needed since font is variable; */
	font-style: normal;
	font-display: swap;
}
@font-face {
	font-family: "Alegreya";
	src: url("data:font/ttf;base64,")
		format("truetype-variations");
	/* font-weight: not needed since font is variable; */
	font-style: italic;
	font-display: swap;
}
@font-face {
	font-family: "Times New Roman";
	src: url("data:font/ttf;base64,")
		format("truetype");
	font-style: normal;
	font-weight: normal;
	font-display: swap;
}
@font-face {
	font-family: "Times New Roman";
	src: url("data:font/ttf;base64,")
		format("truetype");
	font-style: normal;
	font-weight: bold;
	font-display: swap;
}
@font-face {
	font-family: "Times New Roman";
	src: url("data:font/ttf;base64,")
		format("truetype");
	font-style: italic;
	font-weight: normal;
	font-display: swap;
}
@font-face {
	font-family: "Times New Roman";
	src: url("data:font/ttf;base64,")
		format("truetype");
	font-style: italic;
	font-weight: normal;
	font-display: swap;
}

/* --FONT-MONOSPACE, MONOSPACE */
@font-face {
	font-family: "Monaspace Xenon";
	src: url("data:font/otf;base64,")
		format("opentype");
	font-weight: normal;
	font-style: normal;
	font-display: swap;
}
@font-face {
	font-family: "IBM Plex Mono";
	src: url("data:font/ttf;base64,")
		format("truetype");
	font-weight: normal;
	font-style: normal;
	font-display: swap;
}

/* EMOJI */
/* https://meowni.ca/posts/og-emoji-font/ */
@font-face {
	font-family: "DoCoMo Emoji";
	src: url("data:font/ttf;base64,")
		format("truetype");
	font-display: swap;
}

@font-face {
	font-family: "Noto Emoji";
	src: url("data:font/ttf;base64,")
		format("truetype");
	font-display: swap;
}

body {
	--font-interface-theme:
		"Alegreya Sans", "Libertinus Sans", "CMU Concrete", "DoCoMo Emoji",
		sans-serif;
	--font-text-theme: "Alegreya", "Times New Roman", "DoCoMo Emoji", serif;
	--font-monospace:
		"Monaspace Xenon", "IBM Plex Mono", "DoCoMo Emoji", monospace;

	font-feature-settings: "pnum", "onum";
	font-variant-ligatures: common-ligatures discretionary-ligatures contextual;

	--font-largest: 1.6em; /* 16/10 */
	--font-larger: 1.391em; /* 16/11.5 */
	--font-large: 1.231em; /* 16/13 */
	--font-normal-size: 1em; /* 1 */
	--font-small: 0.813em; /* 13/16 */
	--font-smaller: 0.719em; /* 11.5/16 */
	--font-smallest: 0.625em; /* 10/16 */

	line-height: 1.5;

	--code-size: var(--font-small);
	--bases-table-font-size: var(--font-normal-size);
}

.cm-hmd-codeblock,
.cm-inline-code,
.cm-templater-command,
code {
	font-feature-settings:
		"liga",
		"calt",
		"ss01",
		"ss02",
		"ss03",
		"ss04",
		"ss05",
		"ss06",
		"ss07",
		"ss08",
		"ss09",
		"ss10",
		"cv01" 0,
		"cv02" 0,
		"cv10" 1,
		"cv31" 1;
}

