	--orange: var(--orange-d-60-even);
	--yellow: var(--yellow-d-60-even);
	--green: var(--green-d-60-even);
	--cyan: var(--cyan-d-60-even);
	--blue: var(--blue-d-45-even);
	--purple: var(--purple-d-45-even);
	--pink: var(--pink-d-60-even);

	--color-red: var(--red);
	--color-orange: var(--orange);
	--color-yellow: var(--yellow);
	--color-green: var(--green);
	--color-cyan: var(--cyan);
	--color-blue: var(--blue);
	--color-purple: var(--purple);
	--color-pink: var(--pink);

	--color-accent: var(--purple);
	--color-accent-1: var(--green);
	--color-accent-2: var(--yellow);

	--background-primary: oklch(0.27 0.005 67);
	--background-primary-alt: oklch(
		from var(--background-primary) calc(l * 0.98) calc(c * 0.98) h
	);
	--background-secondary: oklch(
		from var(--background-primary) calc(l * 1.222) calc(c * 2.6) h
	);
	--background-secondary-alt: oklch(
		from var(--background-secondary) calc(l * 0.9) calc(c * 0.9) h
	);
	--code-background: oklch(
		from var(--background-primary) calc(l * 0.884) calc(c * 0.884) h
	);

	--background-modifier-border: oklch(
		from var(--background-primary) calc(l * 1.222) c h
	);
	--background-modifier-border-hover: oklch(
		from var(--background-primary) calc(l * 1.493) c h
	);
	--background-modifier-border-focus: oklch(
		from var(--background-primary) calc(l * 1.825) c h
	);
	--background-modifier-form-field: oklch(
		from var(--background-primary) calc(l * 0.3) calc(c * 0.3) h
	);
	--background-modifier-form-field-highlight: oklch(
		from var(--background-primary) calc(l * 0.22) calc(c * 0.22) h
	);

	--interactive-normal: oklch(from var(--background-secondary) l c h);
	--interactive-hover: oklch(from var(--background-secondary-alt) l c h);
	--interactive-accent: oklch(from var(--color-accent) l c h);
	--interactive-accent-hover: oklch(from var(--color-accent-1) l c h);

	--text-normal: oklch(0.8 0.035 82);
	--text-muted: oklch(from var(--text-normal) l c h / 0.707);
	--text-faint: oklch(from var(--text-normal) l c h / 0.5);
	/* --text-on-accent: ;
	--text-on-accent-inverted: ; */
	--text-success: oklch(from var(--green) l c h);
	--text-warning: oklch(from var(--orange) l c h);
	--text-error: oklch(from var(--red) l c h);
	--text-accent: oklch(from var(--purple) l c h);
	--text-accent-hover: oklch(from var(--text-accent) calc(l - 0.1) c h);

	--text-selection: oklch(from var(--blue) l c h / 0.3);
	--text-highlight-bg: oklch(from var(--yellow) l c h / 0.1);

	--caret-color: oklch(from var(--text-normal) l c h);

	--vim-cursor: oklch(from var(--color-accent) l c h / 0.8);

	--scrollbar-active-thumb-bg: rgba(255, 255, 255, 0.2);
	--scrollbar-bg: rgba(255, 255, 255, 0.05);
	--scrollbar-thumb-bg: rgba(255, 255, 255, 0.1);
	--highlight-mix-blend-mode: lighten;
}

/* Main (colors) */
body {
	--code-normal: var(--blue);
}

b,
strong,
.cm-strong {
	color: var(--color-accent-1);
}

/* frontmatter */
.shrink-formatting
	.markdown-source-view.mod-cm6
	.cm-line
	span.cm-formatting:not(
		.cm-s-obsidian span.cm-link,
		.cm-s-obsidian span.cm-hmd-internal-link,
		.cm-s-obsidian span.cm-url,
		.cm-s-obsidian span.cm-attribute,
		.cm-s-obsidian span.cm-quote,
		span.cm-hashtag.cm-hashtag-begin,
		.cm-s-obsidian span.cm-formatting-list
	) {
	color: var(--text-faint);
	font-size: var(--font-smaller);
}

/* make workspace frameless */
.workspace-tab-header-container,
.workspace-ribbon.mod-left:before,
.mod-macos.is-hidden-frameless:not(.is-popout-window)
	.sidebar-toggle-button.mod-right {
	background-color: var(--background-primary);
}

/* make graph line colors more viewable */
.graph-view.color-line {
	color: var(--text-faint);
}

/* remove link underline */
:root body {
	--link-decoration: none;
	--link-decoration-hover: underline;
}

/* LINE LENGTHS */
/* https://www.uxpin.com/studio/blog/optimal-line-length-for-readability/ */
.markdown-preview-view {
    --file-line-width: 66ch !important;
}

.markdown-source-view {
    --file-line-width: 88ch !important; /* Ruff python format */
}